function pendingSystems(c){const systems=[];if(c.needs_mainstreet_update&&!c.mainstreet_confirmed_at)systems.push('Mainstreet');if(c.needs_qbo_update&&!c.qbo_confirmed_at)systems.push('QBO');return systems;}
