function casesSorted(cases){const order={Critical:0,High:1,Medium:2,Standard:3};const sort=$('queueSort').value;return [...cases].sort((a,b)=>sort==='balance'?caseValue(b)-caseValue(a):sort==='customer'?a.customer_name.localeCompare(b.customer_name):sort==='followup'?String(a.next_follow_up||'9999').localeCompare(String(b.next_follow_up||'9999')):order[casePriority(a)]-order[casePriority(b)]||caseValue(b)-caseValue(a));}
