 const facts=[['GlassQuest baseline',dollars(c.glassquest_balance)],['Mainstreet balance',dollars(c.mainstreet_balance)],['QBO open balance',dollars(c.qbo_balance)],['Phone',c.phone||'Not in export'],['Contact',c.contact||'Not in export'],['Customer address',[c.street_address,c.city,c.state_code,c.zip_code].filter(Boolean).join(', ')||'Not in export'],['Last purchase (Mainstreet)',c.last_purchase_text||'Not in export'],['Last payment (Mainstreet)',c.last_payment_text||'Not in export'],['EDI status',c.edi_status||'Not in export'],['EDI activity',c.edi_activity||'Not in export'],['Mainstreet imported note',c.source_collection_notes||'No note in this export'],['QBO store',c.qbo_store_name||'Not in export'],['Invoice date',formatDate(c.invoice_date)],['Due date',formatDate(c.due_date)],['Source missing from latest export',sourceCoverage(c).join(' + ')||'None'],['QBO days past due',c.qbo_balance!==null?String(c.qbo_days_past_due):'Not in export'],['Last Mainstreet import',relative(c.mainstreet_seen_at)],['Last QBO import',relative(c.qbo_seen_at)],['Assigned to',state.staff.find(x=>x.auth_user_id===c.assigned_to)?.employee_name||(c.assigned_to?'Staff member':'Not assigned')],['Accounting fixes still needed',pendingSystems(c).join(' + ')||'None']];
 $('caseFacts').innerHTML=facts.map(([k,v])=>`<div class="col-case-fact"><small>${safe(k)}</small><b>${safe(v)}</b></div>`).join('');
