 let neighboring=[];if(customerIds.length){const {data:rows,error}=await supabaseClient.from('collection_source_rows').select('*').in('import_id',customerIds).eq('normalized_customer',c.normalized_customer).neq('transaction_type','invoice').limit(120);if(error)throw error;neighboring=rows||[];}
