function easternMidnight(day){const [yy,mm,dd]=String(day).split('-').map(Number);const guess=new Date(Date.UTC(yy,mm-1,dd));if(!yy||!mm||!dd||Number.isNaN(+guess))throw Error('Invalid report date');const z=easternParts(guess);const wall=Date.UTC(+z.year,+z.month-1,+z.day,+z.hour,+z.minute);return new Date(+guess+(+guess-wall));}
function boundsForDay(day){const start=easternMidnight(day);const next=new Date(Date.parse(day+'T12:00:00Z'));next.setUTCDate(next.getUTCDate()+1);const tomorrow=next.toISOString().slice(0,10);return[start.toISOString(),easternMidnight(tomorrow).toISOString()];}
